// Generates every paste-ready file for the newsletter signup embed from src/.
//   node build.mjs                 -> writes <brand>/{html.html,css.css,js.js,preview.html} + index.html
//   ASSET_BASE=http://... node build.mjs --out <dir>   -> same, into <dir>, with assets from ASSET_BASE
// Edit src/ and re-run; never hand-edit the generated files (each one says so at the top).
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const src = (p) => readFileSync(join(here, 'src', p), 'utf8');
const outArg = process.argv.indexOf('--out');
const out = outArg > -1 ? process.argv[outArg + 1] : here;
const ASSET_BASE = process.env.ASSET_BASE
  || 'https://mhdesigns98.github.io/vpm-widgets/widgets/newsletter-signup-embed/assets/';

const BRANDS = JSON.parse(src('brands.json'));
// Lab preview only: the same block shown in columns of these widths, one per layout tier.
const DEMO_WIDTHS = [
  { px: 1000, label: 'Wide column (800px+)' },
  { px: 680, label: 'Mid column (600-799px)' },
  { px: 480, label: 'Narrow column (under 600px)' },
  { px: 320, label: 'Sidebar / phone (320px)' },
];
const STAMP = 'GENERATED by widgets/newsletter-signup-embed/build.mjs. Edit src/ and re-run; do not edit this file.';
const PRIVACY = 'We respect your privacy. Your information will never be sold. Unsubscribe at any time.';

const coreCss = src('core.css');
const coreJs = src('core.js');

function form(brand) {
  const { u, id } = brand.mailchimp;
  return [
    `<form class="vpm-nls__row" data-nls-form action="https://vpm.us3.list-manage.com/subscribe/post?u=${u}&amp;id=${id}" method="post" target="_blank" novalidate>`,
    `  <input type="email" class="vpm-nls__input" name="EMAIL" placeholder="Enter your email address" aria-label="Email address" required>`,
    `  <div style="position:absolute;left:-5000px;" aria-hidden="true"><input type="text" name="b_${u}_${id}" tabindex="-1" value=""></div>`,
    `  <button type="submit" class="vpm-nls__btn">Keep Me Informed</button>`,
    `</form>`,
    `<div class="vpm-nls__status" data-nls-status role="status" aria-live="polite" hidden></div>`,
  ];
}

// Expands {{form}}, {{privacy[:dark]}} and {{asset:file}}, keeping indentation.
function expand(text, brand) {
  return text
    .replace(/^( *)\{\{form\}\}$/gm, (_, pad) => form(brand).map((l) => pad + l).join('\n'))
    .replace(/\{\{privacy(:dark)?\}\}/g, (_, dark) => `<p class="vpm-nls__privacy${dark ? ' vpm-nls__privacy--dark' : ''}">${PRIVACY}</p>`)
    .replace(/\{\{asset:([\w.-]+)\}\}/g, (_, file) => ASSET_BASE + file)
    .replace(/\{\{[^}]*\}\}/g, (m) => { throw new Error(`unknown placeholder ${m}`); });
}

// The brand's one block, inside the scoping/container wrapper.
function blockFor(slug, brand) {
  const inner = expand(src(`layouts/${slug}.html`), brand).trimEnd();
  return `<div class="vpm-nls vpm-nls--${brand.key}">\n${inner.replace(/^/gm, '  ')}\n</div>`;
}

const demo = (block) => DEMO_WIDTHS.map(({ px, label }) =>
  `<div class="vpm-nls__section-label">${label}</div>\n<div class="vpm-nls__demo" style="max-width:${px}px">\n${block}\n</div>`).join('\n\n');

const fontsLink = (families) =>
  `<link href="https://fonts.googleapis.com/css2?${[...new Set(families)].map((f) => `family=${f}`).join('&')}&family=Public+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">`;

// Preview-only chrome; never part of a paste.
const PREVIEW_CSS = `
  body { margin: 0; padding: 0 24px 48px; background: #fff; }
  .vpm-nls__section-label {
    font-family: 'Oswald', Arial, sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #6b6e6b;
    padding: 32px 0 12px;
  }
  .vpm-nls__demo { width: 100%; }
  .vpm-nls__brand-heading {
    font-family: 'Public Sans', Arial, sans-serif;
    font-size: 22px;
    font-weight: 700;
    color: #101820;
    padding-top: 40px;
    border-bottom: 1px solid #d0d4d8;
    padding-bottom: 8px;
  }`;

const NATIVE_NOTE = `<!--
  Each form POSTs directly to Mailchimp's native embedded-form endpoint: no custom API, no
  backend, no API key. js.js progressively enhances it with an in-page JSONP submit and
  confirmation; with the JS field empty (or on timeout) the native POST still works and
  Mailchimp's response opens in a new tab.
-->`;

function previewDoc({ title, families, css, body }) {
  return `<!DOCTYPE html>
<!-- ${STAMP} -->
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${title}</title>
${fontsLink(families)}
<style>
${css}
${PREVIEW_CSS}
</style>
</head>
<body>
${body}

${NATIVE_NOTE}

<script>
${coreJs}</script>
</body>
</html>
`;
}

const allCss = [coreCss];
const allBodies = [];
const allFamilies = [];

for (const [slug, brand] of Object.entries(BRANDS)) {
  const block = blockFor(slug, brand);
  const theme = expand(src(`themes/${slug}.css`), brand);
  const css = `${coreCss}\n${theme}`;
  const dir = join(out, slug);
  mkdirSync(dir, { recursive: true });

  writeFileSync(join(dir, 'html.html'), `<!-- ================================================
   VPM ${brand.name} Newsletter Signup: HTML block
   ACF field: HTML / Custom HTML. Namespace prefix: vpm-nls-
   One responsive block: it adapts to the width of whatever column it's pasted into
   (full-width section, article body, sidebar), so there are no variants to pick.
   ${STAMP}
   ================================================ -->

${block}

${NATIVE_NOTE}
`);

  writeFileSync(join(dir, 'css.css'), `/* ================================================
   VPM ${brand.name} Newsletter Signup: CSS block
   ACF field: CSS. All rules scoped to .vpm-nls (no global resets).
   ${STAMP}
   ================================================ */

${css}`);

  writeFileSync(join(dir, 'js.js'), `/* VPM newsletter signup: ACF JS field (same file for every brand; safe to paste once per page or per block).
   ${STAMP} */
${coreJs}`);

  const body = demo(block);
  writeFileSync(join(dir, 'preview.html'), previewDoc({
    title: `VPM ${brand.name}: Newsletter Signup`,
    families: [brand.googleFonts],
    css,
    body,
  }));

  allCss.push(theme);
  allFamilies.push(brand.googleFonts);
  allBodies.push(`<h2 class="vpm-nls__brand-heading">${brand.name}</h2>\n${body}`);
  console.log(`${slug}: html.html css.css js.js preview.html`);
}

writeFileSync(join(out, 'index.html'), previewDoc({
  title: 'VPM Newsletter Signup Embed',
  families: allFamilies,
  css: allCss.join('\n'),
  body: allBodies.join('\n\n'),
}));
console.log('index.html');
